  tabId,
  ref: "e12291",
  operation: "click"
});
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2000 });

const snap = await browser.snapshot({ tabId });
const lines = snap.text.split('\n');
const rows = [];
let currentRow = null;

for (let i = 0; i < lines.length; i++) {
  const line = lines[i].trim();
  if (line.startsWith('rowheader "')) {
    const yearMatch = line.match(/rowheader "([^"]+)"/);
    if (yearMatch) {
      currentRow = { year: yearMatch[1], cells: [] };
      rows.push(currentRow);
    }
  } else if (line.startsWith('cell "') && currentRow) {
    const valMatch = line.match(/cell "([^"]+)"/);
    if (valMatch) {
      currentRow.cells.push(valMatch[1]);
    }
  }
}

// Close the modal again to leave the chart showing on screen!
const backRef = snap.text.match(/button "Back" [^\n]*\[ref=(e\d+)\]/)?.[1];
console.log("Back ref:", backRef);
if (backRef) {
  await tool.element_interact({ tabId, ref: backRef, operation: "click" });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2000 });
}

// Scroll chart back into view
await tool.element_interact({
  tabId,
  ref: "e12277",
  operation: "scroll_into_view"
});

console.log("All rows extracted:\n", JSON.stringify(rows, null, 2));

